use soroban_sdk::contracttype;
use sororail_common::impl_single_position_storage;

use crate::types::Stream;

/// Storage keys for the stream contract.
///
/// The whole stream lives in **instance** storage, so it shares one TTL with
/// the contract. The enum has one variant because one instance holds one
/// stream. It is typed so the key encodes the same way across every SoroRail
/// contract.
///
/// Access goes through the helpers generated by
/// `impl_single_position_storage!`, which extend the TTL on every write.
#[contracttype]
pub enum DataKey {
    /// The single stream held by this instance.
    ///
    /// Holds the full [`Stream`] record: parties, rate, span, the `deposited`
    /// total, the running `withdrawn` and `refunded` totals, and the
    /// cancellation timestamp if the stream was cancelled. Accrual is never
    /// stored. It is derived from this record and the ledger timestamp on each
    /// read.
    /// Absent until `create` runs, which is what `NotInitialized` reports.
    Stream,
}

impl_single_position_storage!(Stream, DataKey::Stream);
